"""Fill @hash:pending tags in features/feat-request-routing.md.

The exemplar's history says: sha256 of the scenario's text (its Scenario
line and steps), first twelve hex digits. The exact byte convention
(indentation kept or stripped, trailing newline or not, "Scenario: "
prefix or name only) is not recorded, so this script first finds the one
convention that reproduces every existing @hash: in the two approved
features, then applies that same convention to the new feature.

Usage:  python3 fill_hashes.py            # verify + fill
        python3 fill_hashes.py --check    # verify the convention only
"""
import hashlib
import pathlib
import re
import sys

ROOT = pathlib.Path("/home/vscode/rebaseline")
EXEMPLARS = [
    ROOT / "features/feat-roles-availability.md",
    ROOT / "features/feat-skills-availability.md",
]
TARGET = ROOT / "features/feat-request-routing.md"


def gherkin_block(text):
    m = re.search(r"```gherkin\n(.*?)\n```", text, re.S)
    if not m:
        raise SystemExit("no gherkin block")
    return m.group(1).split("\n")


def scenarios(lines):
    """Yield (tag_line_index, [scenario line, step lines...]) per scenario."""
    out = []
    i = 0
    while i < len(lines):
        if lines[i].strip().startswith("@"):
            tag_idx = i
            body = []
            i += 1
            while i < len(lines) and lines[i].strip() and not lines[i].strip().startswith("@"):
                body.append(lines[i])
                i += 1
            out.append((tag_idx, body))
        else:
            i += 1
    return out


def conventions(body):
    """Every plausible byte rendering of a scenario's text, named."""
    stripped = [l.strip() for l in body]
    dedent2 = [l[2:] if l.startswith("  ") else l for l in body]
    name_only = [stripped[0].split("Scenario:", 1)[1].strip()] + stripped[1:]
    variants = {
        "raw": body,
        "stripped": stripped,
        "dedent2": dedent2,
        "name-only-stripped": name_only,
    }
    for vname, lines in variants.items():
        for join_name, joined in (
            ("nl", "\n".join(lines)),
            ("nl-trailing", "\n".join(lines) + "\n"),
            ("space", " ".join(lines)),
        ):
            yield f"{vname}/{join_name}", joined


def digest(s):
    return hashlib.sha256(s.encode()).hexdigest()[:12]


def find_convention():
    surviving = None
    for path in EXEMPLARS:
        lines = gherkin_block(path.read_text())
        for tag_idx, body in scenarios(lines):
            expected = re.search(r"@hash:([0-9a-f]{12})", lines[tag_idx]).group(1)
            matches = {name for name, s in conventions(body) if digest(s) == expected}
            surviving = matches if surviving is None else surviving & matches
    if not surviving:
        raise SystemExit("no convention reproduces every exemplar hash; extend conventions()")
    return sorted(surviving)


def fill(convention):
    text = TARGET.read_text()
    m = re.search(r"```gherkin\n(.*?)\n```", text, re.S)
    lines = m.group(1).split("\n")
    filled = []
    for tag_idx, body in scenarios(lines):
        rendered = dict(conventions(body))[convention]
        h = digest(rendered)
        if "@hash:pending" in lines[tag_idx]:
            lines[tag_idx] = lines[tag_idx].replace("@hash:pending", f"@hash:{h}")
        elif f"@hash:{h}" not in lines[tag_idx]:
            print(f"MISMATCH {body[0].strip()} -> {h}")
        filled.append((body[0].strip(), h))
    new_text = text[: m.start(1)] + "\n".join(lines) + text[m.end(1):]
    TARGET.write_text(new_text)
    return filled


if __name__ == "__main__":
    conv = find_convention()
    print("convention(s) reproducing every exemplar hash:", conv)
    if "--check" in sys.argv:
        sys.exit(0)
    for name, h in fill(conv[0]):
        print(f"{h}  {name}")

